<?php declare(strict_types=1); ?>
<?php if ($write && $company['role']==='owner'): ?><details class="rounded-panel border border-border bg-surface p-4" <?= $openingInput?'open':'' ?>><summary><?= pl_e(pl_t('Review opening stock quantities and value')) ?></summary><p><?= pl_e(pl_t('Convert existing opening inventory value into product quantities. Values must match the opening journal; confirmation creates no second journal.')) ?></p><form method="post" action="<?= pl_e(pl_url('/inventory')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company,'opening_preview',['request_key'=>$openingInput['request_key']??null]); ?><div class="grid grid-cols-2 md:grid-cols-3 gap-4"><?php pl_starter_field(pl_t('Opening date'),'date',$openingInput['date']??'','date'); pl_starter_field(pl_t('Reason'),'reason',$openingInput['reason']??''); ?></div><?php for ($i=0;$i<max(1,min(500,count($openingInput['lines']??[])));$i++): ?><fieldset class="rounded-panel border border-border p-3 my-3"><legend><?= pl_e(pl_t('Opening product {number}',['number'=>$i+1])) ?></legend><div class="grid grid-cols-2 md:grid-cols-3 gap-4"><?php pl_starter_select(pl_t('Product'),"lines[$i][product_id]",pl_starter_options($stockProducts),$openingInput['lines'][$i]['product_id']??'',false); pl_starter_field(pl_t('Quantity'),"lines[$i][quantity]",$openingInput['lines'][$i]['quantity']??'','text',false); pl_starter_field(pl_t('Opening carrying value'),"lines[$i][amount_base]",$openingInput['lines'][$i]['amount_base']??'','text',false); ?></div><button class="btn btn-ghost btn-sm mt-2" name="remove_line" value="<?= $i ?>" formnovalidate><?= pl_e(pl_t('Remove opening product {number}',['number'=>$i+1])) ?></button></fieldset><?php endfor; ?><button class="btn btn-ghost" name="editor_action" value="add_line" formnovalidate><?= pl_e(pl_t('Add opening product')) ?></button><button class="btn btn-secondary"><?= pl_e(pl_t('Preview opening stock')) ?></button></form></details><?php endif; ?>
<?php if ($preview && $write && $company['role']==='owner'): ?><section class="rounded-panel border border-border bg-surface p-4"><h2><?= pl_e(pl_t('Confirm opening stock')) ?></h2><?php foreach ($preview['payload']['lines'] as $line): ?><p><?= pl_e(pl_t('Product {id} · Quantity {quantity} · Value {amount}',['id'=>(int)$line['product_id'],'quantity'=>$line['quantity'],'amount'=>$line['amount_base']])) ?></p><?php endforeach; ?><form method="post" action="<?= pl_e(pl_url('/inventory')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company,'opening_confirm',['preview_id'=>$confirmInput?($confirmInput['preview_id']??''):$preview['id'],'expected_hash'=>$confirmInput?($confirmInput['expected_hash']??''):$preview['payload_hash'],'request_key'=>$confirmInput['request_key']??null]); ?><p><label><input type="checkbox" name="confirmed" required value="1" <?= ($confirmInput['confirmed']??'')==='1'?'checked':'' ?>> <?= pl_e(pl_t('I reviewed the product quantities and their reconciliation to opening balances.')) ?></label></p><button class="btn btn-primary"><?= pl_e(pl_t('Confirm opening conversion')) ?></button><?php if ($confirmInput): ?><a class="btn btn-secondary" href="<?= pl_e(pl_url('/inventory')) ?>"><?= pl_e(pl_t('Reload current preview')) ?></a><?php endif; ?></form></section><?php endif; ?>
